/* @lc app=leetcode id=2421 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun numberOfGoodPaths(vals: IntArray, edges: Array<IntArray>): Int = IntArray(vals.size) { it }.let { p -> edges.groupBy { maxOf(vals[it[0]], vals[it[1]]) }.let { eg -> vals.indices.groupBy { vals[it] }.toSortedMap().entries.fold(vals.size) { acc, (v, nodes) -> eg[v].orEmpty().forEach { (a, b) -> p[find(p, a)] = find(p, b) }.let { nodes.groupingBy { find(p, it) }.eachCount().values.sumOf { it.toLong() * (it - 1) / 2 }.toInt() + acc } } } } }